module.exports.toolHistory = function toolHistory(title) {
    let results;
    if (title === '多段读取') {
        const lines = Array.from({ length: 260 }, (_, i) => '批次段 ' + (i + 1) + '：原始清点已入暂存区，等待复核签收。');
        lines[128] = '专用核验回执 RZ-6804，状态已核实。';
        results = [{ name: 'read_document', content: lines.join('\n') }];
    } else if (title === '重复调用') {
        results = [2, 5].map(id => ({ name: 'read_sensor', content: '节点 ' + id + '，采样标签 ' + (id === 2 ? 'KJ-216' : 'KJ-618') }));
    } else return [];
    return results.flatMap((r, i) => [
        { role: 'model', content: '', toolCalls: [{ name: r.name, id: 'call-' + i, args: { part: i + 1 } }] },
        { role: 'tool', toolResults: [{ ...r, id: 'call-' + i, isError: false }] }
    ]);
};
